package com.amora.app;
import android.app.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import android.graphics.Color;
/** Local device authentication. Passwords and biometric templates never cross the bridge. */
final class DeviceLock {
 final MainActivity activity; final android.widget.FrameLayout root; View cover; boolean prompting; Runnable success; int change; boolean unlocked;
 DeviceLock(MainActivity a,android.widget.FrameLayout r){activity=a;root=r;}
 boolean enabled(){return activity.getSharedPreferences("amora",0).getBoolean("biometricEnabled",false);}
 void cover(){if(cover!=null)return;LinearLayout layout=new LinearLayout(activity);layout.setOrientation(LinearLayout.VERTICAL);layout.setGravity(Gravity.CENTER);layout.setPadding(32,32,32,32);layout.setBackgroundColor(Color.rgb(25,18,34));TextView title=new TextView(activity);title.setText("Seu cantinho está protegido ♡");title.setTextSize(22);title.setTextColor(Color.WHITE);title.setGravity(Gravity.CENTER);layout.addView(title);Button button=new Button(activity);button.setText("Desbloquear (N)AMORA");button.setOnClickListener(v->authenticate(0,()->{}));layout.addView(button);Button password=new Button(activity);password.setText("Entrar com e-mail e senha");password.setOnClickListener(v->{new AlertDialog.Builder(activity).setMessage("Sair da sessão salva e entrar com sua senha?").setPositiveButton("Usar minha senha",(d,w)->{activity.getSharedPreferences("amora",0).edit().putBoolean("biometricEnabled",false).apply();new NativeBridge(activity,activity.web).clearSession();activity.web.evaluateJavascript("window.dispatchEvent(new CustomEvent('amora-native',{detail:{signOut:true}}))",null);unlock();}).setNegativeButton("Voltar",null).show();});layout.addView(password);cover=layout;root.addView(cover,new android.widget.FrameLayout.LayoutParams(-1,-1));}
 void unlock(){unlocked=true;if(cover!=null){root.removeView(cover);cover=null;}}
 void authenticate(int mode,Runnable after){if(prompting)return;KeyguardManager keyguard=(KeyguardManager)activity.getSystemService(android.content.Context.KEYGUARD_SERVICE);if(!keyguard.isDeviceSecure()){NativeBridge.event("error","Cadastre uma digital ou bloqueio de tela nas configurações do celular.");return;}change=mode;success=after;prompting=true;if(mode==0)cover();if(Build.VERSION.SDK_INT>=28){android.hardware.biometrics.BiometricPrompt.Builder builder=new android.hardware.biometrics.BiometricPrompt.Builder(activity).setTitle("Desbloquear (N)AMORA").setSubtitle("Confirme sua identidade neste celular");if(Build.VERSION.SDK_INT>=29)builder.setDeviceCredentialAllowed(true);else builder.setNegativeButton("Usar PIN",activity.getMainExecutor(),(d,w)->credential());builder.build().authenticate(new CancellationSignal(),activity.getMainExecutor(),new android.hardware.biometrics.BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(android.hardware.biometrics.BiometricPrompt.AuthenticationResult result){complete();}@Override public void onAuthenticationError(int code,CharSequence message){if(Build.VERSION.SDK_INT==28&&(code==11||code==12||code==1)){credential();return;}prompting=false;NativeBridge.event("info","Desbloqueio cancelado. Você pode tentar novamente.");}});}else credential();}
 void credential(){KeyguardManager k=(KeyguardManager)activity.getSystemService(android.content.Context.KEYGUARD_SERVICE);android.content.Intent intent=k.createConfirmDeviceCredentialIntent("(N)AMORA","Confirme o bloqueio deste celular");if(intent!=null)activity.startActivityForResult(intent,49);else prompting=false;}
 void complete(){prompting=false;if(change!=0)activity.getSharedPreferences("amora",0).edit().putBoolean("biometricEnabled",change>0).putBoolean("biometricAsked",true).apply();unlock();NativeBridge.event("biometricUpdated",true);Runnable next=success;success=null;if(next!=null)next.run();}
 void result(int result){prompting=false;if(result==Activity.RESULT_OK)complete();}
 void offer(){if(enabled()||activity.getSharedPreferences("amora",0).getBoolean("biometricAsked",false))return;activity.getSharedPreferences("amora",0).edit().putBoolean("biometricAsked",true).apply();new AlertDialog.Builder(activity).setTitle("Abrir com sua digital?").setMessage("Você pode proteger a sessão salva com a digital ou o bloqueio do celular.").setPositiveButton("Ativar",(d,w)->authenticate(1,()->{})).setNegativeButton("Agora não",null).show();}
}
